import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-rust-cargo-dependency-management-in-rust":{"intro":"In this lab, the concept of development dependencies is explained. Development dependencies are added in the [dev-dependencies] section of the Cargo.toml file and are used for tests, examples, or benchmarks. An example of a development dependency is pretty_assertions, which extends standard macros like assert_eq! and assert_ne! to provide colorful diffs.","steps":[{"title":"Development dependencies","body":["Sometimes there is a need to have dependencies for tests (or examples, or benchmarks) only. Such dependencies are added to Cargo.toml in the [dev-dependencies] section. These dependencies are not propagated to other packages which depend on this package.","One such example is [pretty_assertions](https://docs.rs/pretty_assertions/1.0.0/pretty_assertions/index.html), which extends standard assert_eq! and assert_ne! macros, to provide colorful diff.\\ File Cargo.toml:"],"code":[{"lang":"toml","text":"# standard crate data is left out\n[dev-dependencies]\npretty_assertions = \"1\""},{"lang":"rust","text":"pub fn add(a: i32, b: i32) -> i32 {\n    a + b\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use pretty_assertions::assert_eq; // crate for test-only use. Cannot be used in non-test code.\n\n    #[test]\n    fn test_add() {\n        assert_eq!(add(2, 3), 5);\n    }\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"pub fn add(a: i32, b: i32) -> i32 {\n    a + b\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use pretty_assertions::assert_eq; // crate for test-only use. Cannot be used in non-test code.\n\n    #[test]\n    fn test_add() {\n        assert_eq!(add(2, 3), 5);\n    }\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-exploring-rust-s-unsafe-operations":{"intro":"In this lab, we will explore unsafe operations in Rust, which are used to bypass compiler protections and are typically used for dereferencing raw pointers, calling unsafe functions, accessing or modifying static mutable variables, and implementing unsafe traits. These operations should be minimized in a code base to ensure safety.","steps":[{"title":"Unsafe Operations","body":["As an introduction to this section, to borrow from the official docs, \"one should try to minimize the amount of unsafe code in a code base.\" With that in mind, let's get started! Unsafe annotations in Rust are used to bypass protections put in place by the compiler; specifically, there are four primary things that unsafe is used for:","• dereferencing raw pointers • calling functions or methods which are unsafe (including calling a function over FFI, see [a previous chapter of the book) • accessing or modifying static mutable variables • implementing unsafe traits","Raw pointers * and references &T function similarly, but references are always safe because they are guaranteed to point to valid data due to the borrow checker. Dereferencing a raw pointer can only be done through an unsafe block.","Some functions can be declared as unsafe, meaning it is the programmer's responsibility to ensure correctness instead of the compiler's. One example of this is \\[std::slice::from_raw_parts\\] which will create a slice given a pointer to the first element and a length."],"code":[{"lang":"rust","text":"fn main() {\n    let raw_p: *const u32 = &10;\n\n    unsafe {\n        assert!(*raw_p == 10);\n    }\n}"},{"lang":"rust","text":"use std::slice;\n\nfn main() {\n    let some_vector = vec![1, 2, 3, 4];\n\n    let pointer = some_vector.as_ptr();\n    let length = some_vector.len();\n\n    unsafe {\n        let my_slice: &[u32] = slice::from_raw_parts(pointer, length);\n\n        assert_eq!(some_vector.as_slice(), my_slice);\n    }\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"use std::slice;\n\nfn main() {\n    let some_vector = vec![1, 2, 3, 4];\n\n    let pointer = some_vector.as_ptr();\n    let length = some_vector.len();\n\n    unsafe {\n        let my_slice: &[u32] = slice::from_raw_parts(pointer, length);\n\n        assert_eq!(some_vector.as_slice(), my_slice);\n    }\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-exploring-rust-inline-assembly-usage":{"intro":"In this lab, we will explore the usage of inline assembly in Rust using the asm! macro. We will cover the basic usage of inline assembly, inputs and outputs, late output operands, explicit register operands, clobbered registers, symbol operands and ABI clobbers, register template modifiers, memory address operands, labels, and options for optimizing the assembly code.","steps":[{"title":"Inline assembly","body":["Rust provides support for inline assembly via the asm! macro. It can be used to embed handwritten assembly in the assembly output generated by the compiler. Generally this should not be necessary, but might be where the required performance or timing cannot be otherwise achieved. Accessing low level hardware primitives, e.g. in kernel code, may also demand this functionality.","> **Note**: the examples here are given in x86/x86-64 assembly, but other architectures are also supported.","Inline assembly is currently supported on the following architectures:","• x86 and x86-64 • ARM • AArch64 • RISC-V"],"code":[{"lang":"rust","text":"# #[cfg(target_arch = \"x86_64\")] {\nuse std::arch::asm;\n\nunsafe {\n    asm!(\"nop\");\n}\n# }"},{"lang":"rust","text":"# #[cfg(target_arch = \"x86_64\")] {\nuse std::arch::asm;\n\nlet x: u64;\nunsafe {\n    asm!(\"mov {}, 5\", out(reg) x);\n}\nassert_eq!(x, 5);\n# }"},{"lang":"rust","text":"# #[cfg(target_arch = \"x86_64\")] {\nuse std::arch::asm;\n\nlet i: u64 = 3;\nlet o: u64;\nunsafe {\n    asm!(\n        \"mov {0}, {1}\",\n        \"add {0}, 5\",\n        out(reg) o,\n        in(reg) i,\n    );\n}\nassert_eq!(o, 8);\n# }"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"# #[cfg(target_arch = \"x86_64\")] {\nuse std::arch::asm;\n\nlet i: u64 = 3;\nlet o: u64;\nunsafe {\n    asm!(\n        \"mov {0}, {1}\",\n        \"add {0}, 5\",\n        out(reg) o,\n        in(reg) i,\n    );\n}\nassert_eq!(o, 8);\n# }"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-cargo-documentation-generation-and-testing":{"intro":"In this lab, you can use cargo doc to build documentation in target/doc. You can also use cargo test to run all tests, including documentation tests, and cargo test --doc to only run documentation tests. Doc comments, denoted by ///, are compiled into documentation by rustdoc and support Markdown. These comments are useful for documenting code in big projects. Doc attributes, such as inline, no_inline, and hidden, are frequently used with rustdoc. Rustdoc is widely used by the community for generating documentation, including the standard library docs.","steps":[{"title":"Documentation","body":["Use cargo doc to build documentation in target/doc.","Use cargo test to run all tests (including documentation tests), and cargo test --doc to only run documentation tests.","These commands will appropriately invoke rustdoc (and rustc) as required.","Doc comments are very useful for big projects that require documentation. When running rustdoc, these are the comments that get compiled into documentation. They are denoted by a ///, and support \\[Markdown\\]."],"code":[{"lang":"rust","text":"#![crate_name = \"doc\"]\n\n/// A human being is represented here\npub struct Person {\n    /// A person must have a name, no matter how much Juliet may hate it\n    name: String,\n}\n\nimpl Person {\n    /// Returns a person with the name given them\n    ///\n    /// # Arguments\n    ///\n    /// * `name` - A string slice that holds the name of the person\n    ///\n    /// # Examples\n    ///\n    ///"},{"lang":"text","text":"pub fn new(name: &str) -> Person {\n        Person {\n            name: name.to_string(),\n        }\n    }\n\n    /// Gives a friendly hello!\n    ///\n    /// Says \"Hello, [name](Person::name)\" to the `Person` it is called on.\n    pub fn hello(& self) {\n        println!(\"Hello, {}!\", self.name);\n    }\n}\n\nfn main() {\n    let john = Person::new(\"John\");\n\n    john.hello();\n}"},{"lang":"shell","text":"$ rustc doc.rs --crate-type lib\n$ rustdoc --test --extern doc=\"libdoc.rlib\" doc.rs"}]}],"commands":["rustc doc.rs --crate-type lib"],"reference":[{"path":"reference.sh","text":"$ rustc doc.rs --crate-type lib\n$ rustdoc --test --extern doc=\"libdoc.rlib\" doc.rs"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-rust-casting-explicit-type-conversion":{"intro":"In this lab, we learn about casting in Rust and how to perform explicit type conversion using the as keyword.","steps":[{"title":"Casting","body":["Rust provides no implicit type conversion (coercion) between primitive types. But, explicit type conversion (casting) can be performed using the as keyword.","Rules for converting between integral types follow C conventions generally, except in cases where C has undefined behavior. The behavior of all casts between integral types is well defined in Rust."],"code":[{"lang":"rust","text":"// Suppress all warnings from casts which overflow.\n#![allow(overflowing_literals)]\n\nfn main() {\n    let decimal = 65.4321_f32;\n\n    // Error! No implicit conversion\n    let integer: u8 = decimal;\n    // FIXME ^ Comment out this line\n\n    // Explicit conversion\n    let integer = decimal as u8;\n    let character = integer as char;\n\n    // Error! There are limitations in conversion rules.\n    // A float cannot be directly converted to a char.\n    let character = decimal as char;\n    // FIXME ^ Comment out this line\n\n    println!(\"Casting: {} -> {} -> {}\", decimal, integer, character);\n\n    // when casting any value to an unsigned type, T,\n    // T::MAX + 1 is added or subtracted until the value\n    // fits into the new type\n\n    // 1000 already fits in a u16\n    println!(\"1000 as a u16 is: {}\", 1000 as u16);\n\n    // 1000 - 256 - 256 - 256 = 232\n    // Under the hood, the first 8 least significant bits (LSB) are kept,\n    // while the rest towards the most significant bit (MSB) get truncated.\n    println!(\"1000 as a u8 is : {}\", 1000 as u8);\n    // -1 + 256 = 255\n    println!(\"  -1 as a u8 is : {}\", (-1i8) as u8);\n\n    // For positive numbers, this is the same as the modulus\n    println!(\"1000 mod 256 is : {}\", 1000 % 256);\n\n    // When casting to a signed type, the (bitwise) result is the same as\n    // first casting to the corresponding unsigned type. If the most significant\n    // bit of that value is 1, then the value is negative.\n\n    // Unless it already fits, of course.\n    println!(\" 128 as a i16 is: {}\", 128 as i16);\n\n    // In boundary case 128 value in 8-bit two's complement representation is -128\n    println!(\" 128 as a i8 is : {}\", 128 as i8);"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"// Suppress all warnings from casts which overflow.\n#![allow(overflowing_literals)]\n\nfn main() {\n    let decimal = 65.4321_f32;\n\n    // Error! No implicit conversion\n    let integer: u8 = decimal;\n    // FIXME ^ Comment out this line\n\n    // Explicit conversion\n    let integer = decimal as u8;\n    let character = integer as char;\n\n    // Error! There are limitations in conversion rules.\n    // A float cannot be directly converted to a char.\n    let character = decimal as char;\n    // FIXME ^ Comment out this line\n\n    println!(\"Casting: {} -> {} -> {}\", decimal, integer, character);\n\n    // when casting any value to an unsigned type, T,\n    // T::MAX + 1 is added or subtracted until the value\n    // fits into the new type\n\n    // 1000 already fits in a u16\n    println!(\"1000 as a u16 is: {}\", 1000 as u16);\n\n    // 1000 - 256 - 256 - 256 = 232\n    // Under the hood, the first 8 least significant bits (LSB) are kept,\n    // while the rest towards the most significant bit (MSB) get truncated.\n    println!(\"1000 as a u8 is : {}\", 1000 as u8);\n    // -1 + 256 = 255\n    println!(\"  -1 as a u8 is : {}\", (-1i8) as u8);\n\n    // For positive numbers, this is the same as the modulus\n    println!(\"1000 mod 256 is : {}\", 1000 % 256);\n\n    // When casting to a signed type, the (bitwise) result is the same as\n    // first casting to the corresponding unsigned type. If the most significant\n    // bit of that value is 1, then the value is negative.\n\n    // Unless it already fits, of course.\n    println!(\" 128 as a i16 is: {}\", 128 as i16);\n\n    // In boundary case 128 value in 8-bit two's complement representation is -128\n    println!(\" 128 as a i8 is : {}\", 128 as i8);"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-from-and-into":{"intro":"In this lab, we explore the concepts of From and Into traits in Rust, which are used for converting between different types. These traits are inherently linked, with Into being the reciprocal of From. The From trait allows a type to define how to create itself from another type, enabling easy conversion between types. The Into trait automatically calls the From implementation when necessary. Both traits can be implemented for custom types, providing flexibility in type conversions.","steps":[{"title":"From and Into","body":["The [From](#from) and [Into](#into) traits are inherently linked, and this is actually part of its implementation. If you are able to convert type A from type B, then it should be easy to believe that we should be able to convert type B to type A.","The [From](#from) trait allows for a type to define how to create itself from another type, hence providing a very simple mechanism for converting between several types. There are numerous implementations of this trait within the standard library for conversion of primitive and common types.","For example we can easily convert a str into a String","We can do similar for defining a conversion for our own type."],"code":[{"lang":"rust","text":"let my_str = \"hello\";\nlet my_string = String::from(my_str);"},{"lang":"rust","text":"use std::convert::From;\n\n#[derive(Debug)]\nstruct Number {\n    value: i32,\n}\n\nimpl From<i32> for Number {\n    fn from(item: i32) -> Self {\n        Number { value: item }\n    }\n}\n\nfn main() {\n    let num = Number::from(30);\n    println!(\"My number is {:?}\", num);\n}"},{"lang":"rust","text":"use std::convert::Into;\n\n#[derive(Debug)]\nstruct Number {\n    value: i32,\n}\n\nimpl Into<Number> for i32 {\n    fn into(self) -> Number {\n        Number { value: self }\n    }\n}\n\nfn main() {\n    let int = 5;\n    // Try removing the type annotation\n    let num: Number = int.into();\n    println!(\"My number is {:?}\", num);\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"use std::convert::Into;\n\n#[derive(Debug)]\nstruct Number {\n    value: i32,\n}\n\nimpl Into<Number> for i32 {\n    fn into(self) -> Number {\n        Number { value: self }\n    }\n}\n\nfn main() {\n    let int = 5;\n    // Try removing the type annotation\n    let num: Number = int.into();\n    println!(\"My number is {:?}\", num);\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-tryfrom-and-tryinto":{"intro":"In this lab, we explore the usage of TryFrom and TryInto in Rust, which are generic traits used for fallible conversions between types and return Result types. We provide an example code snippet that demonstrates the implementation of TryFrom for converting an i32 into a custom EvenNumber struct, and then showcase how to use TryFrom and TryInto to perform the conversion and handle the possible errors.","steps":[{"title":"TryFrom and TryInto","body":["Similar to From and Into, \\[TryFrom\\] and \\[TryInto\\] are generic traits for converting between types. Unlike From/Into, the TryFrom/TryInto traits are used for fallible conversions, and as such, return \\[Result\\]s."],"code":[{"lang":"rust","text":"use std::convert::TryFrom;\nuse std::convert::TryInto;\n\n#[derive(Debug, PartialEq)]\nstruct EvenNumber(i32);\n\nimpl TryFrom<i32> for EvenNumber {\n    type Error = ();\n\n    fn try_from(value: i32) -> Result<Self, Self::Error> {\n        if value % 2 == 0 {\n            Ok(EvenNumber(value))\n        } else {\n            Err(())\n        }\n    }\n}\n\nfn main() {\n    // TryFrom\n\n    assert_eq!(EvenNumber::try_from(8), Ok(EvenNumber(8)));\n    assert_eq!(EvenNumber::try_from(5), Err(()));\n\n    // TryInto\n\n    let result: Result<EvenNumber, ()> = 8i32.try_into();\n    assert_eq!(result, Ok(EvenNumber(8)));\n    let result: Result<EvenNumber, ()> = 5i32.try_into();\n    assert_eq!(result, Err(()));\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"use std::convert::TryFrom;\nuse std::convert::TryInto;\n\n#[derive(Debug, PartialEq)]\nstruct EvenNumber(i32);\n\nimpl TryFrom<i32> for EvenNumber {\n    type Error = ();\n\n    fn try_from(value: i32) -> Result<Self, Self::Error> {\n        if value % 2 == 0 {\n            Ok(EvenNumber(value))\n        } else {\n            Err(())\n        }\n    }\n}\n\nfn main() {\n    // TryFrom\n\n    assert_eq!(EvenNumber::try_from(8), Ok(EvenNumber(8)));\n    assert_eq!(EvenNumber::try_from(5), Err(()));\n\n    // TryInto\n\n    let result: Result<EvenNumber, ()> = 8i32.try_into();\n    assert_eq!(result, Ok(EvenNumber(8)));\n    let result: Result<EvenNumber, ()> = 5i32.try_into();\n    assert_eq!(result, Err(()));\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-to-and-from-strings":{"intro":"In this lab, we will learn about converting to and from strings in Rust. To convert any type to a string, we can implement the ToString trait for the type. Alternatively, we can implement the fmt::Display trait, which automatically provides the ToString trait and allows us to print the type using println!. On the other hand, to parse a string into a specific type, such as a number, we can use the parse function along with type inference or by specifying the type using the 'turbofish' syntax. This relies on the FromStr trait, which is implemented for many types in the standard library. If we want to parse a string into a user-defined type, we can implement the FromStr trait for that type.","steps":[{"title":"To and from Strings","body":["To convert any type to a String is as simple as implementing the \\[ToString\\] trait for the type. Rather than doing so directly, you should implement the fmt::Display trait which automagically provides \\[ToString\\] and also allows printing the type as discussed in the section on print!.","One of the more common types to convert a string into a number. The idiomatic approach to this is to use the \\[parse\\] function and either to arrange for type inference or to specify the type to parse using the 'turbofish' syntax. Both alternatives are shown in the following example.","This will convert the string into the type specified as long as the \\[FromStr\\] trait is implemented for that type. This is implemented for numerous types within the standard library. To obtain this functionality on a user defined type simply implement the \\[FromStr\\] trait for that type."],"code":[{"lang":"rust","text":"use std::fmt;\n\nstruct Circle {\n    radius: i32\n}\n\nimpl fmt::Display for Circle {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, \"Circle of radius {}\", self.radius)\n    }\n}\n\nfn main() {\n    let circle = Circle { radius: 6 };\n    println!(\"{}\", circle.to_string());\n}"},{"lang":"rust","text":"fn main() {\n    let parsed: i32 = \"5\".parse().unwrap();\n    let turbo_parsed = \"10\".parse::<i32>().unwrap();\n\n    let sum = parsed + turbo_parsed;\n    println!(\"Sum: {:?}\", sum);\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"fn main() {\n    let parsed: i32 = \"5\".parse().unwrap();\n    let turbo_parsed = \"10\".parse::<i32>().unwrap();\n\n    let sum = parsed + turbo_parsed;\n    println!(\"Sum: {:?}\", sum);\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-binding-and-destructuring-in-rust":{"intro":"In this lab, the concept of binding in Rust is explored, which allows for indirect access to variables and the ability to branch and use that variable without re-binding. The @ sigil in the match statement is used for binding values to names. Examples are provided, including how to bind values to a specific range and how to 'destructure' enum variants like Option.","steps":[{"title":"Binding","body":["Indirectly accessing a variable makes it impossible to branch and use that variable without re-binding. match provides the @ sigil for binding values to names:","You can also use binding to \"destructure\" enum variants, such as Option:"],"code":[{"lang":"rust","text":"// A function `age` which returns a `u32`.\nfn age() -> u32 {\n    15\n}\n\nfn main() {\n    println!(\"Tell me what type of person you are\");\n\n    match age() {\n        0             => println!(\"I haven't celebrated my first birthday yet\"),\n        // Could `match` 1 ..= 12 directly but then what age\n        // would the child be? Instead, bind to `n` for the\n        // sequence of 1 ..= 12. Now the age can be reported.\n        n @ 1  ..= 12 => println!(\"I'm a child of age {:?}\", n),\n        n @ 13 ..= 19 => println!(\"I'm a teen of age {:?}\", n),\n        // Nothing bound. Return the result.\n        n             => println!(\"I'm an old person of age {:?}\", n),\n    }\n}"},{"lang":"rust","text":"fn some_number() -> Option<u32> {\n    Some(42)\n}\n\nfn main() {\n    match some_number() {\n        // Got `Some` variant, match if its value, bound to `n`,\n        // is equal to 42.\n        Some(n @ 42) => println!(\"The Answer: {}!\", n),\n        // Match any other number.\n        Some(n)      => println!(\"Not interesting... {}\", n),\n        // Match anything else (`None` variant).\n        _            => (),\n    }\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"fn some_number() -> Option<u32> {\n    Some(42)\n}\n\nfn main() {\n    match some_number() {\n        // Got `Some` variant, match if its value, bound to `n`,\n        // is equal to 42.\n        Some(n @ 42) => println!(\"The Answer: {}!\", n),\n        // Match any other number.\n        Some(n)      => println!(\"Not interesting... {}\", n),\n        // Match anything else (`None` variant).\n        _            => (),\n    }\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-concise-rust-pattern-matching-with-let-else":{"intro":"In this lab, the use of let-else in Rust is demonstrated, where a refutable pattern can match and bind variables in the surrounding scope, or else diverge when the pattern doesn't match by using statements like break, return, or panic!. This construct allows for concise and readable code when dealing with pattern matching and error handling scenarios, eliminating the need for repeating code blocks or using outer let statements.","steps":[{"title":"let-else","body":["With let-else, a refutable pattern can match and bind variables in the surrounding scope like a normal let, or else diverge (e.g. break, return, panic!) when the pattern doesn't match.","The scope of name bindings is the main thing that makes this different from match or if let-else expressions. You could previously approximate these patterns with an unfortunate bit of repetition and an outer let:"],"code":[{"lang":"rust","text":"use std::str::FromStr;\n\nfn get_count_item(s: &str) -> (u64, &str) {\n    let mut it = s.split(' ');\n    let (Some(count_str), Some(item)) = (it.next(), it.next()) else {\n        panic!(\"Can't segment count item pair: '{s}'\");\n    };\n    let Ok(count) = u64::from_str(count_str) else {\n        panic!(\"Can't parse integer: '{count_str}'\");\n    };\n    (count, item)\n}\n\nfn main() {\n    assert_eq!(get_count_item(\"3 chairs\"), (3, \"chairs\"));\n}"},{"lang":"rust","text":"use std::str::FromStr;\n\nfn get_count_item(s: &str) -> (u64, &str) {\n    let mut it = s.split(' ');\n    let (count_str, item) = match (it.next(), it.next()) {\n        (Some(count_str), Some(item)) => (count_str, item),\n        _ => panic!(\"Can't segment count item pair: '{s}'\"),\n    };\n    let count = if let Ok(count) = u64::from_str(count_str) {\n        count\n    } else {\n        panic!(\"Can't parse integer: '{count_str}'\");\n    };\n        (count, item)\n    }\n\n    assert_eq!(get_count_item(\"3 chairs\"), (3, \"chairs\"));"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"use std::str::FromStr;\n\nfn get_count_item(s: &str) -> (u64, &str) {\n    let mut it = s.split(' ');\n    let (count_str, item) = match (it.next(), it.next()) {\n        (Some(count_str), Some(item)) => (count_str, item),\n        _ => panic!(\"Can't segment count item pair: '{s}'\"),\n    };\n    let count = if let Ok(count) = u64::from_str(count_str) {\n        count\n    } else {\n        panic!(\"Can't parse integer: '{count_str}'\");\n    };\n        (count, item)\n    }\n\n    assert_eq!(get_count_item(\"3 chairs\"), (3, \"chairs\"));"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-writing-rust-functions":{"intro":"In this lab, we learn how to write functions in Rust. Functions are declared using the fn keyword, and their arguments are type annotated. The return type, if applicable, is specified after an arrow ->. The final expression in the function serves as the return value, but the return statement can be used to return a value earlier. The lab provides an example of rewriting the FizzBuzz program using functions, demonstrating the use of functions that return boolean values, functions that return the unit type (), and functions without specified return types.","steps":[{"title":"Functions","body":["Functions are declared using the fn keyword. Its arguments are type annotated, just like variables, and, if the function returns a value, the return type must be specified after an arrow ->.","The final expression in the function will be used as return value. Alternatively, the return statement can be used to return a value earlier from within the function, even from inside loops or if statements.","Let's rewrite FizzBuzz using functions!"],"code":[{"lang":"rust","text":"// Unlike C/C++, there's no restriction on the order of function definitions\nfn main() {\n    // We can use this function here, and define it somewhere later\n    fizzbuzz_to(100);\n}\n\n// Function that returns a boolean value\nfn is_divisible_by(lhs: u32, rhs: u32) -> bool {\n    // Corner case, early return\n    if rhs == 0 {\n        return false;\n    }\n\n    // This is an expression, the `return` keyword is not necessary here\n    lhs % rhs == 0\n}\n\n// Functions that \"don't\" return a value, actually return the unit type `()`\nfn fizzbuzz(n: u32) -> () {\n    if is_divisible_by(n, 15) {\n        println!(\"fizzbuzz\");\n    } else if is_divisible_by(n, 3) {\n        println!(\"fizz\");\n    } else if is_divisible_by(n, 5) {\n        println!(\"buzz\");\n    } else {\n        println!(\"{}\", n);\n    }\n}\n\n// When a function returns `()`, the return type can be omitted from the\n// signature\nfn fizzbuzz_to(n: u32) {\n    for n in 1..=n {\n        fizzbuzz(n);\n    }\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"// Unlike C/C++, there's no restriction on the order of function definitions\nfn main() {\n    // We can use this function here, and define it somewhere later\n    fizzbuzz_to(100);\n}\n\n// Function that returns a boolean value\nfn is_divisible_by(lhs: u32, rhs: u32) -> bool {\n    // Corner case, early return\n    if rhs == 0 {\n        return false;\n    }\n\n    // This is an expression, the `return` keyword is not necessary here\n    lhs % rhs == 0\n}\n\n// Functions that \"don't\" return a value, actually return the unit type `()`\nfn fizzbuzz(n: u32) -> () {\n    if is_divisible_by(n, 15) {\n        println!(\"fizzbuzz\");\n    } else if is_divisible_by(n, 3) {\n        println!(\"fizz\");\n    } else if is_divisible_by(n, 5) {\n        println!(\"buzz\");\n    } else {\n        println!(\"{}\", n);\n    }\n}\n\n// When a function returns `()`, the return type can be omitted from the\n// signature\nfn fizzbuzz_to(n: u32) {\n    for n in 1..=n {\n        fizzbuzz(n);\n    }\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-associated-functions-methods":{"intro":"In this lab, we define a Point struct with associated functions origin() and new(), and a Rectangle struct with methods area(), perimeter(), and translate(). We also introduce a Pair struct with a method destroy(). We demonstrate how to use these functions and methods by creating instances of the structs and calling the respective functions and methods on them.","steps":[{"title":"Associated functions & Methods","body":["Associated functions & Methods","Some functions are connected to a particular type. These come in two forms: associated functions, and methods. Associated functions are functions that are defined on a type generally, while methods are associated functions that are called on a particular instance of a type."],"code":[{"lang":"rust","text":"struct Point {\n    x: f64,\n    y: f64,\n}\n\n// Implementation block, all `Point` associated functions & methods go in here\nimpl Point {\n    // This is an \"associated function\" because this function is associated with\n    // a particular type, that is, Point.\n    //\n    // Associated functions don't need to be called with an instance.\n    // These functions are generally used like constructors.\n    fn origin() -> Point {\n        Point { x: 0.0, y: 0.0 }\n    }\n\n    // Another associated function, taking two arguments:\n    fn new(x: f64, y: f64) -> Point {\n        Point { x: x, y: y }\n    }\n}\n\nstruct Rectangle {\n    p1: Point,\n    p2: Point,\n}\n\nimpl Rectangle {\n    // This is a method\n    // `&self` is sugar for `self: &Self`, where `Self` is the type of the\n    // caller object. In this case `Self` = `Rectangle`\n    fn area(&self) -> f64 {\n        // `self` gives access to the struct fields via the dot operator\n        let Point { x: x1, y: y1 } = self.p1;\n        let Point { x: x2, y: y2 } = self.p2;\n\n        // `abs` is a `f64` method that returns the absolute value of the\n        // caller\n        ((x1 - x2) * (y1 - y2)).abs()\n    }\n\n    fn perimeter(&self) -> f64 {\n        let Point { x: x1, y: y1 } = self.p1;\n        let Point { x: x2, y: y2 } = self.p2;\n\n        2.0 * ((x1 - x2).abs() + (y1 - y2).abs())\n    }"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"struct Point {\n    x: f64,\n    y: f64,\n}\n\n// Implementation block, all `Point` associated functions & methods go in here\nimpl Point {\n    // This is an \"associated function\" because this function is associated with\n    // a particular type, that is, Point.\n    //\n    // Associated functions don't need to be called with an instance.\n    // These functions are generally used like constructors.\n    fn origin() -> Point {\n        Point { x: 0.0, y: 0.0 }\n    }\n\n    // Another associated function, taking two arguments:\n    fn new(x: f64, y: f64) -> Point {\n        Point { x: x, y: y }\n    }\n}\n\nstruct Rectangle {\n    p1: Point,\n    p2: Point,\n}\n\nimpl Rectangle {\n    // This is a method\n    // `&self` is sugar for `self: &Self`, where `Self` is the type of the\n    // caller object. In this case `Self` = `Rectangle`\n    fn area(&self) -> f64 {\n        // `self` gives access to the struct fields via the dot operator\n        let Point { x: x1, y: y1 } = self.p1;\n        let Point { x: x2, y: y2 } = self.p2;\n\n        // `abs` is a `f64` method that returns the absolute value of the\n        // caller\n        ((x1 - x2) * (y1 - y2)).abs()\n    }\n\n    fn perimeter(&self) -> f64 {\n        let Point { x: x1, y: y1 } = self.p1;\n        let Point { x: x2, y: y2 } = self.p2;\n\n        2.0 * ((x1 - x2).abs() + (y1 - y2).abs())\n    }"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-exploring-rust-closures-and-capturing-behavi":{"intro":"In this lab, we explore closures in Rust and their capturing behavior, which allows them to capture variables by reference, mutable reference, or value, depending on the requirements of the closure.","steps":[{"title":"Capturing","body":["Closures are inherently flexible and will do what the functionality requires to make the closure work without annotation. This allows capturing to flexibly adapt to the use case, sometimes moving and sometimes borrowing. Closures can capture variables:","• by reference: &T • by mutable reference: &mut T • by value: T","They preferentially capture variables by reference and only go lower when required.","Using move before vertical pipes forces closure to take ownership of captured variables:"],"code":[{"lang":"rust","text":"fn main() {\n    use std::mem;\n\n    let color = String::from(\"green\");\n\n    // A closure to print `color` which immediately borrows (`&`) `color` and\n    // stores the borrow and closure in the `print` variable. It will remain\n    // borrowed until `print` is used the last time.\n    //\n    // `println!` only requires arguments by immutable reference so it doesn't\n    // impose anything more restrictive.\n    let print = || println!(\"`color`: {}\", color);\n\n    // Call the closure using the borrow.\n    print();\n\n    // `color` can be borrowed immutably again, because the closure only holds\n    // an immutable reference to `color`.\n    let _reborrow = &color;\n    print();\n\n    // A move or reborrow is allowed after the final use of `print`\n    let _color_moved = color;\n\n\n    let mut count = 0;\n    // A closure to increment `count` could take either `&mut count` or `count`\n    // but `&mut count` is less restrictive so it takes that. Immediately\n    // borrows `count`.\n    //\n    // A `mut` is required on `inc` because a `&mut` is stored inside. Thus,\n    // calling the closure mutates the closure which requires a `mut`.\n    let mut inc = || {\n        count += 1;\n        println!(\"`count`: {}\", count);\n    };\n\n    // Call the closure using a mutable borrow.\n    inc();\n\n    // The closure still mutably borrows `count` because it is called later.\n    // An attempt to reborrow will lead to an error.\n    // let _reborrow = &count;\n    // ^ TODO: try uncommenting this line.\n    inc();\n\n    // The closure no longer needs to borrow `&mut count`. Therefore, it is\n    // possible to reborrow without an error"},{"lang":"rust","text":"fn main() {\n    // `Vec` has non-copy semantics.\n    let haystack = vec![1, 2, 3];\n\n    let contains = move |needle| haystack.contains(needle);\n\n    println!(\"{}\", contains(&1));\n    println!(\"{}\", contains(&4));\n\n    // println!(\"There're {} elements in vec\", haystack.len());\n    // ^ Uncommenting above line will result in compile-time error\n    // because borrow checker doesn't allow re-using variable after it\n    // has been moved.\n\n    // Removing `move` from closure's signature will cause closure\n    // to borrow _haystack_ variable immutably, hence _haystack_ is still\n    // available and uncommenting above line will not cause an error.\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"fn main() {\n    // `Vec` has non-copy semantics.\n    let haystack = vec![1, 2, 3];\n\n    let contains = move |needle| haystack.contains(needle);\n\n    println!(\"{}\", contains(&1));\n    println!(\"{}\", contains(&4));\n\n    // println!(\"There're {} elements in vec\", haystack.len());\n    // ^ Uncommenting above line will result in compile-time error\n    // because borrow checker doesn't allow re-using variable after it\n    // has been moved.\n\n    // Removing `move` from closure's signature will cause closure\n    // to borrow _haystack_ variable immutably, hence _haystack_ is still\n    // available and uncommenting above line will not cause an error.\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-as-input-parameters":{"intro":"In this lab, we learn that when writing functions in Rust that take a closure as an input parameter, the closure's complete type must be annotated using one of the traits: Fn, FnMut, or FnOnce, which determine how the closure uses the captured value, either by reference, mutable reference, or value. The compiler captures variables in the least restrictive manner possible based on the chosen trait for the closure.","steps":[{"title":"As input parameters","body":["While Rust chooses how to capture variables on the fly mostly without type annotation, this ambiguity is not allowed when writing functions. When taking a closure as an input parameter, the closure's complete type must be annotated using one of a few traits, and they're determined by what the closure does with captured value. In order of decreasing restriction, they are:","• Fn: the closure uses the captured value by reference (&T) • FnMut: the closure uses the captured value by mutable reference (&mut T) • FnOnce: the closure uses the captured value by value (T)","On a variable-by-variable basis, the compiler will capture variables in the least restrictive manner possible.","For instance, consider a parameter annotated as FnOnce. This specifies that the closure _may_ capture by &T, &mut T, or T, but the compiler will ultimately choose based on how the captured variables are used in the closure."],"code":[{"lang":"rust","text":"// A function which takes a closure as an argument and calls it.\n// <F> denotes that F is a \"Generic type parameter\"\nfn apply<F>(f: F) where\n    // The closure takes no input and returns nothing.\n    F: FnOnce() {\n    // ^ TODO: Try changing this to `Fn` or `FnMut`.\n\n    f();\n}\n\n// A function which takes a closure and returns an `i32`.\nfn apply_to_3<F>(f: F) -> i32 where\n    // The closure takes an `i32` and returns an `i32`.\n    F: Fn(i32) -> i32 {\n\n    f(3)\n}\n\nfn main() {\n    use std::mem;\n\n    let greeting = \"hello\";\n    // A non-copy type.\n    // `to_owned` creates owned data from borrowed one\n    let mut farewell = \"goodbye\".to_owned();\n\n    // Capture 2 variables: `greeting` by reference and\n    // `farewell` by value.\n    let diary = || {\n        // `greeting` is by reference: requires `Fn`.\n        println!(\"I said {}.\", greeting);\n\n        // Mutation forces `farewell` to be captured by\n        // mutable reference. Now requires `FnMut`.\n        farewell.push_str(\"!!!\");\n        println!(\"Then I screamed {}.\", farewell);\n        println!(\"Now I can sleep. zzzzz\");\n\n        // Manually calling drop forces `farewell` to\n        // be captured by value. Now requires `FnOnce`.\n        mem::drop(farewell);\n    };\n\n    // Call the function which applies the closure.\n    apply(diary);\n\n    // `double` satisfies `apply_to_3`'s trait bound\n    let double = |x| 2 * x;"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"// A function which takes a closure as an argument and calls it.\n// <F> denotes that F is a \"Generic type parameter\"\nfn apply<F>(f: F) where\n    // The closure takes no input and returns nothing.\n    F: FnOnce() {\n    // ^ TODO: Try changing this to `Fn` or `FnMut`.\n\n    f();\n}\n\n// A function which takes a closure and returns an `i32`.\nfn apply_to_3<F>(f: F) -> i32 where\n    // The closure takes an `i32` and returns an `i32`.\n    F: Fn(i32) -> i32 {\n\n    f(3)\n}\n\nfn main() {\n    use std::mem;\n\n    let greeting = \"hello\";\n    // A non-copy type.\n    // `to_owned` creates owned data from borrowed one\n    let mut farewell = \"goodbye\".to_owned();\n\n    // Capture 2 variables: `greeting` by reference and\n    // `farewell` by value.\n    let diary = || {\n        // `greeting` is by reference: requires `Fn`.\n        println!(\"I said {}.\", greeting);\n\n        // Mutation forces `farewell` to be captured by\n        // mutable reference. Now requires `FnMut`.\n        farewell.push_str(\"!!!\");\n        println!(\"Then I screamed {}.\", farewell);\n        println!(\"Now I can sleep. zzzzz\");\n\n        // Manually calling drop forces `farewell` to\n        // be captured by value. Now requires `FnOnce`.\n        mem::drop(farewell);\n    };\n\n    // Call the function which applies the closure.\n    apply(diary);\n\n    // `double` satisfies `apply_to_3`'s trait bound\n    let double = |x| 2 * x;"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-as-output-parameters":{"intro":"In this lab, we learn that closures can be used as input parameters and can also be returned as output parameters by utilizing impl Trait and specifying the valid traits (Fn, FnMut, FnOnce). The move keyword is used to indicate that all captures occur by value, avoiding invalid references.","steps":[{"title":"As output parameters","body":["Closures as input parameters are possible, so returning closures as output parameters should also be possible. However, anonymous closure types are, by definition, unknown, so we have to use impl Trait to return them.","The valid traits for returning a closure are:","Beyond this, the move keyword must be used, which signals that all captures occur by value. This is required because any captures by reference would be dropped as soon as the function exited, leaving invalid references in the closure."],"code":[{"lang":"rust","text":"fn create_fn() -> impl Fn() {\n    let text = \"Fn\".to_owned();\n\n    move || println!(\"This is a: {}\", text)\n}\n\nfn create_fnmut() -> impl FnMut() {\n    let text = \"FnMut\".to_owned();\n\n    move || println!(\"This is a: {}\", text)\n}\n\nfn create_fnonce() -> impl FnOnce() {\n    let text = \"FnOnce\".to_owned();\n\n    move || println!(\"This is a: {}\", text)\n}\n\nfn main() {\n    let fn_plain = create_fn();\n    let mut fn_mut = create_fnmut();\n    let fn_once = create_fnonce();\n\n    fn_plain();\n    fn_mut();\n    fn_once();\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"fn create_fn() -> impl Fn() {\n    let text = \"Fn\".to_owned();\n\n    move || println!(\"This is a: {}\", text)\n}\n\nfn create_fnmut() -> impl FnMut() {\n    let text = \"FnMut\".to_owned();\n\n    move || println!(\"This is a: {}\", text)\n}\n\nfn create_fnonce() -> impl FnOnce() {\n    let text = \"FnOnce\".to_owned();\n\n    move || println!(\"This is a: {}\", text)\n}\n\nfn main() {\n    let fn_plain = create_fn();\n    let mut fn_mut = create_fnmut();\n    let fn_once = create_fnonce();\n\n    fn_plain();\n    fn_mut();\n    fn_once();\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-exploring-rust-iterator-s-any-function":{"intro":"In this lab, the Iterator::any function is discussed, which is a function that takes an iterator as input and returns true if any element in the iterator satisfies a given predicate, and false otherwise. The function is defined as a trait method in Rust's standard library and can be used on any type that implements the Iterator trait. The function takes a closure as an argument, which determines the predicate to be applied to each element in the iterator. The closure is defined with the FnMut trait, meaning that it can modify captured variables but not consume them. The any function returns a boolean value indicating whether the predicate is satisfied by any element in the iterator.","steps":[{"title":"Iterator::any","body":["Iterator::any is a function which when passed an iterator, will return true if any element satisfies the predicate. Otherwise false. Its signature:"],"code":[{"lang":"rust","text":"pub trait Iterator {\n    // The type being iterated over.\n    type Item;\n\n    // `any` takes `&mut self` meaning the caller may be borrowed\n    // and modified, but not consumed.\n    fn any<F>(&mut self, f: F) -> bool where\n        // `FnMut` meaning any captured variable may at most be\n        // modified, not consumed. `Self::Item` states it takes\n        // arguments to the closure by value.\n        F: FnMut(Self::Item) -> bool;\n}"},{"lang":"rust","text":"fn main() {\n    let vec1 = vec![1, 2, 3];\n    let vec2 = vec![4, 5, 6];\n\n    // `iter()` for vecs yields `&i32`. Destructure to `i32`.\n    println!(\"2 in vec1: {}\", vec1.iter()     .any(|&x| x == 2));\n    // `into_iter()` for vecs yields `i32`. No destructuring required.\n    println!(\"2 in vec2: {}\", vec2.into_iter().any(|x| x == 2));\n\n    // `iter()` only borrows `vec1` and its elements, so they can be used again\n    println!(\"vec1 len: {}\", vec1.len());\n    println!(\"First element of vec1 is: {}\", vec1[0]);\n    // `into_iter()` does move `vec2` and its elements, so they cannot be used again\n    // println!(\"First element of vec2 is: {}\", vec2[0]);\n    // println!(\"vec2 len: {}\", vec2.len());\n    // TODO: uncomment two lines above and see compiler errors.\n\n    let array1 = [1, 2, 3];\n    let array2 = [4, 5, 6];\n\n    // `iter()` for arrays yields `&i32`.\n    println!(\"2 in array1: {}\", array1.iter()     .any(|&x| x == 2));\n    // `into_iter()` for arrays yields `i32`.\n    println!(\"2 in array2: {}\", array2.into_iter().any(|x| x == 2));\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"fn main() {\n    let vec1 = vec![1, 2, 3];\n    let vec2 = vec![4, 5, 6];\n\n    // `iter()` for vecs yields `&i32`. Destructure to `i32`.\n    println!(\"2 in vec1: {}\", vec1.iter()     .any(|&x| x == 2));\n    // `into_iter()` for vecs yields `i32`. No destructuring required.\n    println!(\"2 in vec2: {}\", vec2.into_iter().any(|x| x == 2));\n\n    // `iter()` only borrows `vec1` and its elements, so they can be used again\n    println!(\"vec1 len: {}\", vec1.len());\n    println!(\"First element of vec1 is: {}\", vec1[0]);\n    // `into_iter()` does move `vec2` and its elements, so they cannot be used again\n    // println!(\"First element of vec2 is: {}\", vec2[0]);\n    // println!(\"vec2 len: {}\", vec2.len());\n    // TODO: uncomment two lines above and see compiler errors.\n\n    let array1 = [1, 2, 3];\n    let array2 = [4, 5, 6];\n\n    // `iter()` for arrays yields `&i32`.\n    println!(\"2 in array1: {}\", array1.iter()     .any(|&x| x == 2));\n    // `into_iter()` for arrays yields `i32`.\n    println!(\"2 in array2: {}\", array2.into_iter().any(|x| x == 2));\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-searching-through-iterators":{"intro":"In this lab, we learn about the Iterator::find function in Rust, which iterates over an iterator and searches for the first value that satisfies a given condition. If none of the values satisfy the condition, it returns None.","steps":[{"title":"Searching through iterators","body":["Iterator::find is a function which iterates over an iterator and searches for the first value which satisfies some condition. If none of the values satisfy the condition, it returns None. Its signature:","Iterator::find gives you a reference to the item. But if you want the _index_ of the item, use Iterator::position."],"code":[{"lang":"rust","text":"pub trait Iterator {\n    // The type being iterated over.\n    type Item;\n\n    // `find` takes `&mut self` meaning the caller may be borrowed\n    // and modified, but not consumed.\n    fn find<P>(&mut self, predicate: P) -> Option<Self::Item> where\n        // `FnMut` meaning any captured variable may at most be\n        // modified, not consumed. `&Self::Item` states it takes\n        // arguments to the closure by reference.\n        P: FnMut(&Self::Item) -> bool;\n}"},{"lang":"rust","text":"fn main() {\n    let vec1 = vec![1, 2, 3];\n    let vec2 = vec![4, 5, 6];\n\n    // `iter()` for vecs yields `&i32`.\n    let mut iter = vec1.iter();\n    // `into_iter()` for vecs yields `i32`.\n    let mut into_iter = vec2.into_iter();\n\n    // `iter()` for vecs yields `&i32`, and we want to reference one of its\n    // items, so we have to destructure `&&i32` to `i32`\n    println!(\"Find 2 in vec1: {:?}\", iter     .find(|&&x| x == 2));\n    // `into_iter()` for vecs yields `i32`, and we want to reference one of\n    // its items, so we have to destructure `&i32` to `i32`\n    println!(\"Find 2 in vec2: {:?}\", into_iter.find(| &x| x == 2));\n\n    let array1 = [1, 2, 3];\n    let array2 = [4, 5, 6];\n\n    // `iter()` for arrays yields `&&i32`\n    println!(\"Find 2 in array1: {:?}\", array1.iter()     .find(|&&x| x == 2));\n    // `into_iter()` for arrays yields `&i32`\n    println!(\"Find 2 in array2: {:?}\", array2.into_iter().find(|&x| x == 2));\n}"},{"lang":"rust","text":"fn main() {\n    let vec = vec![1, 9, 3, 3, 13, 2];\n\n    // `iter()` for vecs yields `&i32` and `position()` does not take a reference, so\n    // we have to destructure `&i32` to `i32`\n    let index_of_first_even_number = vec.iter().position(|&x| x % 2 == 0);\n    assert_eq!(index_of_first_even_number, Some(5));\n\n    // `into_iter()` for vecs yields `i32` and `position()` does not take a reference, so\n    // we do not have to destructure\n    let index_of_first_negative_number = vec.into_iter().position(|x| x < 0);\n    assert_eq!(index_of_first_negative_number, None);\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"fn main() {\n    let vec = vec![1, 9, 3, 3, 13, 2];\n\n    // `iter()` for vecs yields `&i32` and `position()` does not take a reference, so\n    // we have to destructure `&i32` to `i32`\n    let index_of_first_even_number = vec.iter().position(|&x| x % 2 == 0);\n    assert_eq!(index_of_first_even_number, Some(5));\n\n    // `into_iter()` for vecs yields `i32` and `position()` does not take a reference, so\n    // we do not have to destructure\n    let index_of_first_negative_number = vec.into_iter().position(|x| x < 0);\n    assert_eq!(index_of_first_negative_number, None);\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-diverging-functions-in-rust":{"intro":"In this lab, we learn about diverging functions that are marked using ! in Rust. Diverging functions never return and their return type is an empty type. This is different from the () type which has only one possible value. Diverging functions can be useful when casting to any other type is required, such as in match branches. They are also the return type of functions that loop forever or terminate the process.","steps":[{"title":"Diverging functions","body":["Diverging functions never return. They are marked using !, which is an empty type.","As opposed to all the other types, this one cannot be instantiated, because the set of all possible values this type can have is empty. Note that, it is different from the () type, which has exactly one possible value.","For example, this function returns as usual, although there is no information in the return value.","As opposed to this function, which will never return the control back to the caller."],"code":[{"lang":"rust","text":"fn foo() -> ! {\n    panic!(\"This call never returns.\");\n}"},{"lang":"rust","text":"fn some_fn() {\n    ()\n}\n\nfn main() {\n    let _a: () = some_fn();\n    println!(\"This function returns and you can see this line.\");\n}"},{"lang":"rust","text":"#![feature(never_type)]\n\nfn main() {\n    let x: ! = panic!(\"This call never returns.\");\n    println!(\"You will never see this line!\");\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"#![feature(never_type)]\n\nfn main() {\n    let x: ! = panic!(\"This call never returns.\");\n    println!(\"You will never see this line!\");\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-the-use-declaration":{"intro":"In this lab, we will explore the use declaration in Rust, which allows us to bind a full path to a new name for easier access, and can be used with the as keyword to bind imports to a different name. Example code snippets demonstrate how to use the use declaration to simplify accessing functions and modules within nested paths.","steps":[{"title":"The use declaration","body":["The use declaration can be used to bind a full path to a new name, for easier access. It is often used like this:","You can use the as keyword to bind imports to a different name:"],"code":[{"lang":"rust","text":"use crate::deeply::nested::{\n    my_first_function,\n    my_second_function,\n    AndATraitType\n};\n\nfn main() {\n    my_first_function();\n}"},{"lang":"rust","text":"// Bind the `deeply::nested::function` path to `other_function`.\nuse deeply::nested::function as other_function;\n\nfn function() {\n    println!(\"called `function()`\");\n}\n\nmod deeply {\n    pub mod nested {\n        pub fn function() {\n            println!(\"called `deeply::nested::function()`\");\n        }\n    }\n}\n\nfn main() {\n    // Easier access to `deeply::nested::function`\n    other_function();\n\n    println!(\"Entering block\");\n    {\n        // This is equivalent to `use deeply::nested::function as function`.\n        // This `function()` will shadow the outer one.\n        use crate::deeply::nested::function;\n\n        // `use` bindings have a local scope. In this case, the\n        // shadowing of `function()` is only in this block.\n        function();\n\n        println!(\"Leaving block\");\n    }\n\n    function();\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"// Bind the `deeply::nested::function` path to `other_function`.\nuse deeply::nested::function as other_function;\n\nfn function() {\n    println!(\"called `function()`\");\n}\n\nmod deeply {\n    pub mod nested {\n        pub fn function() {\n            println!(\"called `deeply::nested::function()`\");\n        }\n    }\n}\n\nfn main() {\n    // Easier access to `deeply::nested::function`\n    other_function();\n\n    println!(\"Entering block\");\n    {\n        // This is equivalent to `use deeply::nested::function as function`.\n        // This `function()` will shadow the outer one.\n        use crate::deeply::nested::function;\n\n        // `use` bindings have a local scope. In this case, the\n        // shadowing of `function()` is only in this block.\n        function();\n\n        println!(\"Leaving block\");\n    }\n\n    function();\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-modular-rust-file-organization":{"intro":"In this lab, the file hierarchy of the modules in the code example can be represented as follows: There is a directory named 'my' which contains two files, 'inaccessible.rs' and 'nested.rs'. Additionally, there is a file named 'my.rs' and a file named 'split.rs'. The 'split.rs' file includes the module 'my' which is defined in the 'my.rs' file, and the 'my.rs' file includes the modules 'inaccessible' and 'nested' which are defined in the 'inaccessible.rs' and 'nested.rs' files respectively.","steps":[{"title":"File hierarchy","body":["Modules can be mapped to a file/directory hierarchy. Let's break down the visibility example in files:","Let's check that things still work as before:"],"code":[{"lang":"shell","text":"$ tree .\n.\n├── my\n│   ├── inaccessible.rs\n│   └── nested.rs\n├── my.rs\n└── split.rs"},{"lang":"rust","text":"// This declaration will look for a file named `my.rs` and will\n// insert its contents inside a module named `my` under this scope\nmod my;\n\nfn function() {\n    println!(\"called `function()`\");\n}\n\nfn main() {\n    my::function();\n\n    function();\n\n    my::indirect_access();\n\n    my::nested::function();\n}"},{"lang":"rust","text":"// Similarly `mod inaccessible` and `mod nested` will locate the `nested.rs`\n// and `inaccessible.rs` files and insert them here under their respective\n// modules\nmod inaccessible;\npub mod nested;\n\npub fn function() {\n    println!(\"called `my::function()`\");\n}\n\nfn private_function() {\n    println!(\"called `my::private_function()`\");\n}\n\npub fn indirect_access() {\n    print!(\"called `my::indirect_access()`, that\\n> \");\n\n    private_function();\n}"}]}],"commands":["rustc split.rs && ./split"],"reference":[{"path":"reference.rs","text":"// Similarly `mod inaccessible` and `mod nested` will locate the `nested.rs`\n// and `inaccessible.rs` files and insert them here under their respective\n// modules\nmod inaccessible;\npub mod nested;\n\npub fn function() {\n    println!(\"called `my::function()`\");\n}\n\nfn private_function() {\n    println!(\"called `my::private_function()`\");\n}\n\npub fn indirect_access() {\n    print!(\"called `my::indirect_access()`, that\\n> \");\n\n    private_function();\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-creating-a-library":{"intro":"In this lab, we will create a library called rary in Rust. The rary library contains a public function called public_function, a private function called private_function, and an indirect access function called indirect_access. Afterwards, we compile the library using the rustc command, resulting in a file named library.rlib.","steps":[{"title":"Creating a Library","body":["Let's create a library, and then see how to link it to another crate.","Libraries get prefixed with \"lib\", and by default they get named after their crate file, but this default name can be overridden by passing the --crate-name option to rustc or by using the \\[crate_name attribute\\]\\[crate-name\\]."],"code":[{"lang":"rust","text":"pub fn public_function() {\n    println!(\"called rary's `public_function()`\");\n}\n\nfn private_function() {\n    println!(\"called rary's `private_function()`\");\n}\n\npub fn indirect_access() {\n    print!(\"called rary's `indirect_access()`, that\\n> \");\n\n    private_function();\n}"},{"lang":"shell","text":"$ rustc --crate-type=lib rary.rs\n$ ls lib*\nlibrary.rlib"}]}],"commands":["rustc --crate-type=lib rary.rs","ls lib*"],"reference":[{"path":"reference.sh","text":"$ rustc --crate-type=lib rary.rs\n$ ls lib*\nlibrary.rlib"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-rust-software-testing-fundamentals":{"intro":"In this lab, we will explore the importance of testing in software development using Rust and how to write different types of tests such as unit tests and integration tests. We will also learn about organizing tests in Rust projects and running them using the cargo test command. Additionally, we will discuss the potential issues that can arise from running tests concurrently and provide an example to illustrate this.","steps":[{"title":"Testing","body":["As we know testing is integral to any piece of software! Rust has first-class support for unit and integration testing ([see this chapter](https://doc.rust-lang.org/book/ch11-00-testing.html) in TRPL).","From the testing chapters linked above, we see how to write unit tests and integration tests. Organizationally, we can place unit tests in the modules they test and integration tests in their own tests/ directory:","Each file in tests is a separate [integration test](https://doc.rust-lang.org/book/ch11-03-test-organization.html#integration-tests), i.e. a test that is meant to test your library as if it were being called from a dependent crate.","The Testing chapter elaborates on the three different testing styles: Unit, Doc, and Integration."],"code":[{"lang":"txt","text":"foo\n├── Cargo.toml\n├── src\n│   └── main.rs\n│   └── lib.rs\n└── tests\n    ├── my_test.rs\n    └── my_other_test.rs"},{"lang":"shell","text":"$ cargo test"},{"lang":"shell","text":"[object Object]"}]}],"commands":["cargo test","cargo test test_foo","cat ferris.txt"],"reference":[{"path":"reference.sh","text":"[object Object]"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-disabling-rust-unused-code-warnings":{"intro":"In this lab, the compiler provides a dead_code lint that warns about unused functions, but you can use attributes, such as #[allow(dead_code)], to disable the lint and prevent the warnings.","steps":[{"title":"dead_code","body":["The compiler provides a dead_code _lint_ that will warn about unused functions. An _attribute_ can be used to disable the lint.","Note that in real programs, you should eliminate dead code. In these examples we'll allow dead code in some places because of the interactive nature of the examples."],"code":[{"lang":"rust","text":"fn used_function() {}\n\n// `#[allow(dead_code)]` is an attribute that disables the `dead_code` lint\n#[allow(dead_code)]\nfn unused_function() {}\n\nfn noisy_unused_function() {}\n// FIXME ^ Add an attribute to suppress the warning\n\nfn main() {\n    used_function();\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"fn used_function() {}\n\n// `#[allow(dead_code)]` is an attribute that disables the `dead_code` lint\n#[allow(dead_code)]\nfn unused_function() {}\n\nfn noisy_unused_function() {}\n// FIXME ^ Add an attribute to suppress the warning\n\nfn main() {\n    used_function();\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-cargo-attributes-in-rust-development":{"intro":"In this lab, it is explained that the crate_type and crate_name attributes in Rust have no effect when using Cargo, the Rust package manager, which is widely used for Rust projects.","steps":[{"title":"Crates","body":["The crate_type attribute can be used to tell the compiler whether a crate is a binary or a library (and even which type of library), and the crate_name attribute can be used to set the name of the crate.","However, it is important to note that both the crate_type and crate_name attributes have **no** effect whatsoever when using Cargo, the Rust package manager. Since Cargo is used for the majority of Rust projects, this means real-world uses of crate_type and crate_name are relatively limited.","When the crate_type attribute is used, we no longer need to pass the --crate-type flag to rustc."],"code":[{"lang":"rust","text":"// This crate is a library\n#![crate_type = \"lib\"]\n// The library is named \"rary\"\n#![crate_name = \"rary\"]\n\npub fn public_function() {\n    println!(\"called rary's `public_function()`\");\n}\n\nfn private_function() {\n    println!(\"called rary's `private_function()`\");\n}\n\npub fn indirect_access() {\n    print!(\"called rary's `indirect_access()`, that\\n> \");\n\n    private_function();\n}"},{"lang":"shell","text":"$ rustc lib.rs\n$ ls lib*\nlibrary.rlib"}]}],"commands":["rustc lib.rs","ls lib*"],"reference":[{"path":"reference.sh","text":"$ rustc lib.rs\n$ ls lib*\nlibrary.rlib"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-conditional-compilation-with-rust-s-cfg-attr":{"intro":"In this lab, you will learn about the cfg attribute and cfg! macro in Rust, which allow for conditional checks in configuration and evaluation, respectively. The cfg attribute enables conditional compilation, while the cfg! macro evaluates to true or false at run-time. Code blocks using cfg! must be valid regardless of the evaluation result, unlike #[cfg] which can remove code.","steps":[{"title":"cfg","body":["Configuration conditional checks are possible through two different operators:","• the cfg attribute: #[cfg(...)] in attribute position • the cfg! macro: cfg!(...) in boolean expressions","While the former enables conditional compilation, the latter conditionally evaluates to true or false literals allowing for checks at run-time. Both utilize identical argument syntax.","cfg!, unlike #[cfg], does not remove any code and only evaluates to true or false. For example, all blocks in an if/else expression need to be valid when cfg! is used for the condition, regardless of what cfg! is evaluating."],"code":[{"lang":"rust","text":"// This function only gets compiled if the target OS is linux\n#[cfg(target_os = \"linux\")]\nfn are_you_on_linux() {\n    println!(\"You are running linux!\");\n}\n\n// And this function only gets compiled if the target OS is *not* linux\n#[cfg(not(target_os = \"linux\"))]\nfn are_you_on_linux() {\n    println!(\"You are *not* running linux!\");\n}\n\nfn main() {\n    are_you_on_linux();\n\n    println!(\"Are you sure?\");\n    if cfg!(target_os = \"linux\") {\n        println!(\"Yes. It's definitely linux!\");\n    } else {\n        println!(\"Yes. It's definitely *not* linux!\");\n    }\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"// This function only gets compiled if the target OS is linux\n#[cfg(target_os = \"linux\")]\nfn are_you_on_linux() {\n    println!(\"You are running linux!\");\n}\n\n// And this function only gets compiled if the target OS is *not* linux\n#[cfg(not(target_os = \"linux\"))]\nfn are_you_on_linux() {\n    println!(\"You are *not* running linux!\");\n}\n\nfn main() {\n    are_you_on_linux();\n\n    println!(\"Are you sure?\");\n    if cfg!(target_os = \"linux\") {\n        println!(\"Yes. It's definitely linux!\");\n    } else {\n        println!(\"Yes. It's definitely *not* linux!\");\n    }\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-conditional-rust-function-compilation":{"intro":"In this lab, we have a code snippet that includes a function called conditional_function(), but it will only be compiled and executed if a custom conditional called some_condition is passed to rustc using the --cfg flag.","steps":[{"title":"Custom","body":["Some conditionals like target_os are implicitly provided by rustc, but custom conditionals must be passed to rustc using the --cfg flag.","Try to run this to see what happens without the custom cfg flag."],"code":[{"lang":"rust","text":"#[cfg(some_condition)]\nfn conditional_function() {\n    println!(\"condition met!\");\n}\n\nfn main() {\n    conditional_function();\n}"},{"lang":"shell","text":"$ rustc --cfg some_condition custom.rs && ./custom\ncondition met!"}]}],"commands":["rustc --cfg some_condition custom.rs && ./custom"],"reference":[{"path":"reference.sh","text":"$ rustc --cfg some_condition custom.rs && ./custom\ncondition met!"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-defining-generic-functions-in-rust":{"intro":"In this lab, you will learn how to define generic functions in Rust. To make a function generic, you need to prepend the type T with <T>. Sometimes, you may need to explicitly specify type parameters while calling a generic function, which can be done using the syntax fun::<A, B, ...>(). The code provided demonstrates the usage of generic functions in Rust and includes examples of functions that are both generic and non-generic.","steps":[{"title":"Functions","body":["The same set of rules can be applied to functions: a type T becomes generic when preceded by <T>.","Using generic functions sometimes requires explicitly specifying type parameters. This may be the case if the function is called where the return type is generic, or if the compiler doesn't have enough information to infer the necessary type parameters.","A function call with explicitly specified type parameters looks like: fun::<A, B, ...>()."],"code":[{"lang":"rust","text":"struct A;          // Concrete type `A`.\nstruct S(A);       // Concrete type `S`.\nstruct SGen<T>(T); // Generic type `SGen`.\n\n// The following functions all take ownership of the variable passed into\n// them and immediately go out of scope, freeing the variable.\n\n// Define a function `reg_fn` that takes an argument `_s` of type `S`.\n// This has no `<T>` so this is not a generic function.\nfn reg_fn(_s: S) {}\n\n// Define a function `gen_spec_t` that takes an argument `_s` of type `SGen<T>`.\n// It has been explicitly given the type parameter `A`, but because `A` has not\n// been specified as a generic type parameter for `gen_spec_t`, it is not generic.\nfn gen_spec_t(_s: SGen<A>) {}\n\n// Define a function `gen_spec_i32` that takes an argument `_s` of type `SGen<i32>`.\n// It has been explicitly given the type parameter `i32`, which is a specific type.\n// Because `i32` is not a generic type, this function is also not generic.\nfn gen_spec_i32(_s: SGen<i32>) {}\n\n// Define a function `generic` that takes an argument `_s` of type `SGen<T>`.\n// Because `SGen<T>` is preceded by `<T>`, this function is generic over `T`.\nfn generic<T>(_s: SGen<T>) {}\n\nfn main() {\n    // Using the non-generic functions\n    reg_fn(S(A));          // Concrete type.\n    gen_spec_t(SGen(A));   // Implicitly specified type parameter `A`.\n    gen_spec_i32(SGen(6)); // Implicitly specified type parameter `i32`.\n\n    // Explicitly specified type parameter `char` to `generic()`.\n    generic::<char>(SGen('a'));\n\n    // Implicitly specified type parameter `char` to `generic()`.\n    generic(SGen('c'));\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"struct A;          // Concrete type `A`.\nstruct S(A);       // Concrete type `S`.\nstruct SGen<T>(T); // Generic type `SGen`.\n\n// The following functions all take ownership of the variable passed into\n// them and immediately go out of scope, freeing the variable.\n\n// Define a function `reg_fn` that takes an argument `_s` of type `S`.\n// This has no `<T>` so this is not a generic function.\nfn reg_fn(_s: S) {}\n\n// Define a function `gen_spec_t` that takes an argument `_s` of type `SGen<T>`.\n// It has been explicitly given the type parameter `A`, but because `A` has not\n// been specified as a generic type parameter for `gen_spec_t`, it is not generic.\nfn gen_spec_t(_s: SGen<A>) {}\n\n// Define a function `gen_spec_i32` that takes an argument `_s` of type `SGen<i32>`.\n// It has been explicitly given the type parameter `i32`, which is a specific type.\n// Because `i32` is not a generic type, this function is also not generic.\nfn gen_spec_i32(_s: SGen<i32>) {}\n\n// Define a function `generic` that takes an argument `_s` of type `SGen<T>`.\n// Because `SGen<T>` is preceded by `<T>`, this function is generic over `T`.\nfn generic<T>(_s: SGen<T>) {}\n\nfn main() {\n    // Using the non-generic functions\n    reg_fn(S(A));          // Concrete type.\n    gen_spec_t(SGen(A));   // Implicitly specified type parameter `A`.\n    gen_spec_i32(SGen(6)); // Implicitly specified type parameter `i32`.\n\n    // Explicitly specified type parameter `char` to `generic()`.\n    generic::<char>(SGen('a'));\n\n    // Implicitly specified type parameter `char` to `generic()`.\n    generic(SGen('c'));\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-implement-generic-double-deallocation-trait":{"intro":"In this lab, a generic DoubleDrop trait is defined, which includes a double_drop method that allows a type to deallocate itself and an input parameter.","steps":[{"title":"Traits","body":["Of course traits can also be generic. Here we define one which reimplements the Drop trait as a generic method to drop itself and an input."],"code":[{"lang":"rust","text":"// Non-copyable types.\nstruct Empty;\nstruct Null;\n\n// A trait generic over `T`.\ntrait DoubleDrop<T> {\n    // Define a method on the caller type which takes an\n    // additional single parameter `T` and does nothing with it.\n    fn double_drop(self, _: T);\n}\n\n// Implement `DoubleDrop<T>` for any generic parameter `T` and\n// caller `U`.\nimpl<T, U> DoubleDrop<T> for U {\n    // This method takes ownership of both passed arguments,\n    // deallocating both.\n    fn double_drop(self, _: T) {}\n}\n\nfn main() {\n    let empty = Empty;\n    let null  = Null;\n\n    // Deallocate `empty` and `null`.\n    empty.double_drop(null);\n\n    //empty;\n    //null;\n    // ^ TODO: Try uncommenting these lines.\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"// Non-copyable types.\nstruct Empty;\nstruct Null;\n\n// A trait generic over `T`.\ntrait DoubleDrop<T> {\n    // Define a method on the caller type which takes an\n    // additional single parameter `T` and does nothing with it.\n    fn double_drop(self, _: T);\n}\n\n// Implement `DoubleDrop<T>` for any generic parameter `T` and\n// caller `U`.\nimpl<T, U> DoubleDrop<T> for U {\n    // This method takes ownership of both passed arguments,\n    // deallocating both.\n    fn double_drop(self, _: T) {}\n}\n\nfn main() {\n    let empty = Empty;\n    let null  = Null;\n\n    // Deallocate `empty` and `null`.\n    empty.double_drop(null);\n\n    //empty;\n    //null;\n    // ^ TODO: Try uncommenting these lines.\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-rust-generics-type-constraints":{"intro":"In this lab, when working with generics in Rust, type parameters must be bounded by traits to specify the functionality a type must implement.","steps":[{"title":"Bounds","body":["When working with generics, the type parameters often must use traits as _bounds_ to stipulate what functionality a type implements. For example, the following example uses the trait Display to print and so it requires T to be bound by Display; that is, T _must_ implement Display.","Bounding restricts the generic to types that conform to the bounds. That is:","Another effect of bounding is that generic instances are allowed to access the \\[methods\\] of traits specified in the bounds. For example:","As an additional note, where clauses can also be used to apply bounds in some cases to be more expressive."],"code":[{"lang":"rust","text":"// Define a function `printer` that takes a generic type `T` which\n// must implement trait `Display`.\nfn printer<T: Display>(t: T) {\n    println!(\"{}\", t);\n}"},{"lang":"rust","text":"struct S<T: Display>(T);\n\n// Error! `Vec<T>` does not implement `Display`. This\n// specialization will fail.\nlet s = S(vec![1]);"},{"lang":"rust","text":"// A trait which implements the print marker: `{:?}`.\nuse std::fmt::Debug;\n\ntrait HasArea {\n    fn area(&self) -> f64;\n}\n\nimpl HasArea for Rectangle {\n    fn area(&self) -> f64 { self.length * self.height }\n}\n\n#[derive(Debug)]\nstruct Rectangle { length: f64, height: f64 }\n#[allow(dead_code)]\nstruct Triangle  { length: f64, height: f64 }\n\n// The generic `T` must implement `Debug`. Regardless\n// of the type, this will work properly.\nfn print_debug<T: Debug>(t: &T) {\n    println!(\"{:?}\", t);\n}\n\n// `T` must implement `HasArea`. Any type which meets\n// the bound can access `HasArea`'s function `area`.\nfn area<T: HasArea>(t: &T) -> f64 { t.area() }\n\nfn main() {\n    let rectangle = Rectangle { length: 3.0, height: 4.0 };\n    let _triangle = Triangle  { length: 3.0, height: 4.0 };\n\n    print_debug(&rectangle);\n    println!(\"Area: {}\", area(&rectangle));\n\n    //print_debug(&_triangle);\n    //println!(\"Area: {}\", area(&_triangle));\n    // ^ TODO: Try uncommenting these.\n    // | Error: Does not implement either `Debug` or `HasArea`.\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"// A trait which implements the print marker: `{:?}`.\nuse std::fmt::Debug;\n\ntrait HasArea {\n    fn area(&self) -> f64;\n}\n\nimpl HasArea for Rectangle {\n    fn area(&self) -> f64 { self.length * self.height }\n}\n\n#[derive(Debug)]\nstruct Rectangle { length: f64, height: f64 }\n#[allow(dead_code)]\nstruct Triangle  { length: f64, height: f64 }\n\n// The generic `T` must implement `Debug`. Regardless\n// of the type, this will work properly.\nfn print_debug<T: Debug>(t: &T) {\n    println!(\"{:?}\", t);\n}\n\n// `T` must implement `HasArea`. Any type which meets\n// the bound can access `HasArea`'s function `area`.\nfn area<T: HasArea>(t: &T) -> f64 { t.area() }\n\nfn main() {\n    let rectangle = Rectangle { length: 3.0, height: 4.0 };\n    let _triangle = Triangle  { length: 3.0, height: 4.0 };\n\n    print_debug(&rectangle);\n    println!(\"Area: {}\", area(&rectangle));\n\n    //print_debug(&_triangle);\n    //println!(\"Area: {}\", area(&_triangle));\n    // ^ TODO: Try uncommenting these.\n    // | Error: Does not implement either `Debug` or `HasArea`.\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-testcase-empty-bounds":{"intro":"In this lab, the code showcases how traits can be used as bounds, even if the traits do not include any functionality, by using the Eq and Copy traits as examples.","steps":[{"title":"Testcase: empty bounds","body":["A consequence of how bounds work is that even if a trait doesn't include any functionality, you can still use it as a bound. Eq and Copy are examples of such traits from the std library."],"code":[{"lang":"rust","text":"struct Cardinal;\nstruct BlueJay;\nstruct Turkey;\n\ntrait Red {}\ntrait Blue {}\n\nimpl Red for Cardinal {}\nimpl Blue for BlueJay {}\n\n// These functions are only valid for types which implement these\n// traits. The fact that the traits are empty is irrelevant.\nfn red<T: Red>(_: &T)   -> &'static str { \"red\" }\nfn blue<T: Blue>(_: &T) -> &'static str { \"blue\" }\n\nfn main() {\n    let cardinal = Cardinal;\n    let blue_jay = BlueJay;\n    let _turkey   = Turkey;\n\n    // `red()` won't work on a blue jay nor vice versa\n    // because of the bounds.\n    println!(\"A cardinal is {}\", red(&cardinal));\n    println!(\"A blue jay is {}\", blue(&blue_jay));\n    //println!(\"A turkey is {}\", red(&_turkey));\n    // ^ TODO: Try uncommenting this line.\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"struct Cardinal;\nstruct BlueJay;\nstruct Turkey;\n\ntrait Red {}\ntrait Blue {}\n\nimpl Red for Cardinal {}\nimpl Blue for BlueJay {}\n\n// These functions are only valid for types which implement these\n// traits. The fact that the traits are empty is irrelevant.\nfn red<T: Red>(_: &T)   -> &'static str { \"red\" }\nfn blue<T: Blue>(_: &T) -> &'static str { \"blue\" }\n\nfn main() {\n    let cardinal = Cardinal;\n    let blue_jay = BlueJay;\n    let _turkey   = Turkey;\n\n    // `red()` won't work on a blue jay nor vice versa\n    // because of the bounds.\n    println!(\"A cardinal is {}\", red(&cardinal));\n    println!(\"A blue jay is {}\", blue(&blue_jay));\n    //println!(\"A turkey is {}\", red(&_turkey));\n    // ^ TODO: Try uncommenting this line.\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-rust-multiple-bounds-exploration":{"intro":"In this lab, the code demonstrates the concept of multiple bounds in Rust, where a single type can have multiple bounds applied using the + operator.","steps":[{"title":"Multiple bounds","body":["Multiple bounds for a single type can be applied with a +. Like normal, different types are separated with ,."],"code":[{"lang":"rust","text":"use std::fmt::{Debug, Display};\n\nfn compare_prints<T: Debug + Display>(t: &T) {\n    println!(\"Debug: `{:?}`\", t);\n    println!(\"Display: `{}`\", t);\n}\n\nfn compare_types<T: Debug, U: Debug>(t: &T, u: &U) {\n    println!(\"t: `{:?}`\", t);\n    println!(\"u: `{:?}`\", u);\n}\n\nfn main() {\n    let string = \"words\";\n    let array = [1, 2, 3];\n    let vec = vec![1, 2, 3];\n\n    compare_prints(&string);\n    //compare_prints(&array);\n    // TODO ^ Try uncommenting this.\n\n    compare_types(&array, &vec);\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"use std::fmt::{Debug, Display};\n\nfn compare_prints<T: Debug + Display>(t: &T) {\n    println!(\"Debug: `{:?}`\", t);\n    println!(\"Display: `{}`\", t);\n}\n\nfn compare_types<T: Debug, U: Debug>(t: &T, u: &U) {\n    println!(\"t: `{:?}`\", t);\n    println!(\"u: `{:?}`\", u);\n}\n\nfn main() {\n    let string = \"words\";\n    let array = [1, 2, 3];\n    let vec = vec![1, 2, 3];\n\n    compare_prints(&string);\n    //compare_prints(&array);\n    // TODO ^ Try uncommenting this.\n\n    compare_types(&array, &vec);\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-expressive-rust-generics-with-where-clause":{"intro":"In this lab, we learn that a where clause in Rust can be used to express bounds for generic types separately from their declaration, allowing for clearer syntax, and can also apply bounds to arbitrary types rather than just type parameters. The where clause is especially useful when the bounds are more expressive than the normal syntax, as shown in the example involving the PrintInOption trait.","steps":[{"title":"Where clauses","body":["A bound can also be expressed using a where clause immediately before the opening {, rather than at the type's first mention. Additionally, where clauses can apply bounds to arbitrary types, rather than just to type parameters.","Some cases that a where clause is useful:","• When specifying generic types and bounds separately is clearer:","• When using a where clause is more expressive than using normal syntax. The impl in this example cannot be directly expressed without a where clause:"],"code":[{"lang":"rust","text":"impl <A: TraitB + TraitC, D: TraitE + TraitF> MyTrait<A, D> for YourType {}\n\n// Expressing bounds with a `where` clause\nimpl <A, D> MyTrait<A, D> for YourType where\n    A: TraitB + TraitC,\n    D: TraitE + TraitF {}"},{"lang":"rust","text":"use std::fmt::Debug;\n\ntrait PrintInOption {\n    fn print_in_option(self);\n}\n\n// Because we would otherwise have to express this as `T: Debug` or\n// use another method of indirect approach, this requires a `where` clause:\nimpl<T> PrintInOption for T where\n    Option<T>: Debug {\n    // We want `Option<T>: Debug` as our bound because that is what's\n    // being printed. Doing otherwise would be using the wrong bound.\n    fn print_in_option(self) {\n        println!(\"{:?}\", Some(self));\n    }\n}\n\nfn main() {\n    let vec = vec![1, 2, 3];\n\n    vec.print_in_option();\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"use std::fmt::Debug;\n\ntrait PrintInOption {\n    fn print_in_option(self);\n}\n\n// Because we would otherwise have to express this as `T: Debug` or\n// use another method of indirect approach, this requires a `where` clause:\nimpl<T> PrintInOption for T where\n    Option<T>: Debug {\n    // We want `Option<T>: Debug` as our bound because that is what's\n    // being printed. Doing otherwise would be using the wrong bound.\n    fn print_in_option(self) {\n        println!(\"{:?}\", Some(self));\n    }\n}\n\nfn main() {\n    let vec = vec![1, 2, 3];\n\n    vec.print_in_option();\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-new-type-idiom":{"intro":"In this lab, we explore the newtype idiom, which provides compile-time guarantees by allowing us to create a new type that is distinct from its underlying type. An example is shown where a struct Years is used to represent age in years, and a struct Days is used to represent age in days. By using the newtype idiom, we can ensure that the right type of value is supplied to a program, such as in the age verification function old_enough, which requires a value of type Years. Additionally, we learn how to obtain the value of a newtype as its underlying type using tuple or destructuring syntax.","steps":[{"title":"New Type Idiom","body":["The newtype idiom gives compile time guarantees that the right type of value is supplied to a program.","For example, an age verification function that checks age in years, _must_ be given a value of type Years.","Uncomment the last print statement to observe that the type supplied must be Years.","To obtain the newtype's value as the base type, you may use the tuple or destructuring syntax like so:"],"code":[{"lang":"rust","text":"struct Years(i64);\n\nstruct Days(i64);\n\nimpl Years {\n    pub fn to_days(&self) -> Days {\n        Days(self.0 * 365)\n    }\n}\n\n\nimpl Days {\n    /// truncates partial years\n    pub fn to_years(&self) -> Years {\n        Years(self.0 / 365)\n    }\n}\n\nfn old_enough(age: &Years) -> bool {\n    age.0 >= 18\n}\n\nfn main() {\n    let age = Years(5);\n    let age_days = age.to_days();\n    println!(\"Old enough {}\", old_enough(&age));\n    println!(\"Old enough {}\", old_enough(&age_days.to_years()));\n    // println!(\"Old enough {}\", old_enough(&age_days));\n}"},{"lang":"rust","text":"struct Years(i64);\n\nfn main() {\n    let years = Years(42);\n    let years_as_primitive_1: i64 = years.0; // Tuple\n    let Years(years_as_primitive_2) = years; // Destructuring\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"struct Years(i64);\n\nfn main() {\n    let years = Years(42);\n    let years_as_primitive_1: i64 = years.0; // Tuple\n    let Years(years_as_primitive_2) = years; // Destructuring\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-generic-container-trait-implementation":{"intro":"In this lab, we have a trait called Contains that is generic over its container type and requires explicit specification of its generic types when implemented for the Container type.","steps":[{"title":"The Problem","body":["A trait that is generic over its container type has type specification requirements - users of the trait _must_ specify all of its generic types.","In the example below, the Contains trait allows the use of the generic types A and B. The trait is then implemented for the Container type, specifying i32 for A and B so that it can be used with fn difference().","Because Contains is generic, we are forced to explicitly state _all_ of the generic types for fn difference(). In practice, we want a way to express that A and B are determined by the _input_ C. As you will see in the next section, associated types provide exactly that capability."],"code":[{"lang":"rust","text":"struct Container(i32, i32);\n\n// A trait which checks if 2 items are stored inside of container.\n// Also retrieves first or last value.\ntrait Contains<A, B> {\n    fn contains(&self, _: &A, _: &B) -> bool; // Explicitly requires `A` and `B`.\n    fn first(&self) -> i32; // Doesn't explicitly require `A` or `B`.\n    fn last(&self) -> i32;  // Doesn't explicitly require `A` or `B`.\n}\n\nimpl Contains<i32, i32> for Container {\n    // True if the numbers stored are equal.\n    fn contains(&self, number_1: &i32, number_2: &i32) -> bool {\n        (&self.0 == number_1) && (&self.1 == number_2)\n    }\n\n    // Grab the first number.\n    fn first(&self) -> i32 { self.0 }\n\n    // Grab the last number.\n    fn last(&self) -> i32 { self.1 }\n}\n\n// `C` contains `A` and `B`. In light of that, having to express `A` and\n// `B` again is a nuisance.\nfn difference<A, B, C>(container: &C) -> i32 where\n    C: Contains<A, B> {\n    container.last() - container.first()\n}\n\nfn main() {\n    let number_1 = 3;\n    let number_2 = 10;\n\n    let container = Container(number_1, number_2);\n\n    println!(\"Does container contain {} and {}: {}\",\n        &number_1, &number_2,\n        container.contains(&number_1, &number_2));\n    println!(\"First number: {}\", container.first());\n    println!(\"Last number: {}\", container.last());\n\n    println!(\"The difference is: {}\", difference(&container));\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"struct Container(i32, i32);\n\n// A trait which checks if 2 items are stored inside of container.\n// Also retrieves first or last value.\ntrait Contains<A, B> {\n    fn contains(&self, _: &A, _: &B) -> bool; // Explicitly requires `A` and `B`.\n    fn first(&self) -> i32; // Doesn't explicitly require `A` or `B`.\n    fn last(&self) -> i32;  // Doesn't explicitly require `A` or `B`.\n}\n\nimpl Contains<i32, i32> for Container {\n    // True if the numbers stored are equal.\n    fn contains(&self, number_1: &i32, number_2: &i32) -> bool {\n        (&self.0 == number_1) && (&self.1 == number_2)\n    }\n\n    // Grab the first number.\n    fn first(&self) -> i32 { self.0 }\n\n    // Grab the last number.\n    fn last(&self) -> i32 { self.1 }\n}\n\n// `C` contains `A` and `B`. In light of that, having to express `A` and\n// `B` again is a nuisance.\nfn difference<A, B, C>(container: &C) -> i32 where\n    C: Contains<A, B> {\n    container.last() - container.first()\n}\n\nfn main() {\n    let number_1 = 3;\n    let number_2 = 10;\n\n    let container = Container(number_1, number_2);\n\n    println!(\"Does container contain {} and {}: {}\",\n        &number_1, &number_2,\n        container.contains(&number_1, &number_2));\n    println!(\"First number: {}\", container.first());\n    println!(\"Last number: {}\", container.last());\n\n    println!(\"The difference is: {}\", difference(&container));\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-exploring-rust-s-associated-types":{"intro":"In this lab, we explore the concept of associated types in Rust, which allows for improved readability of code by defining inner types locally within a trait as output types. This is achieved by using the type keyword within the trait definition. with associated types, functions that use the trait no longer need to explicitly express the types A and B, making the code more concise and flexible. We rewrite an example from a previous section using associated types to illustrate their usage in practice.","steps":[{"title":"Associated types","body":["The use of \"Associated types\" improves the overall readability of code by moving inner types locally into a trait as _output_ types. Syntax for the trait definition is as follows:","Note that functions that use the trait Contains are no longer required to express A or B at all:","Let's rewrite the example from the previous section using associated types:"],"code":[{"lang":"rust","text":"// `A` and `B` are defined in the trait via the `type` keyword.\n// (Note: `type` in this context is different from `type` when used for\n// aliases).\ntrait Contains {\n    type A;\n    type B;\n\n    // Updated syntax to refer to these new types generically.\n    fn contains(&self, _: &Self::A, _: &Self::B) -> bool;\n}"},{"lang":"rust","text":"// Without using associated types\nfn difference<A, B, C>(container: &C) -> i32 where\n    C: Contains<A, B> { ... }\n\n// Using associated types\nfn difference<C: Contains>(container: &C) -> i32 { ... }"},{"lang":"rust","text":"struct Container(i32, i32);\n\n// A trait which checks if 2 items are stored inside of container.\n// Also retrieves first or last value.\ntrait Contains {\n    // Define generic types here which methods will be able to utilize.\n    type A;\n    type B;\n\n    fn contains(&self, _: &Self::A, _: &Self::B) -> bool;\n    fn first(&self) -> i32;\n    fn last(&self) -> i32;\n}\n\nimpl Contains for Container {\n    // Specify what types `A` and `B` are. If the `input` type\n    // is `Container(i32, i32)`, the `output` types are determined\n    // as `i32` and `i32`.\n    type A = i32;\n    type B = i32;\n\n    // `&Self::A` and `&Self::B` are also valid here.\n    fn contains(&self, number_1: &i32, number_2: &i32) -> bool {\n        (&self.0 == number_1) && (&self.1 == number_2)\n    }\n    // Grab the first number.\n    fn first(&self) -> i32 { self.0 }\n\n    // Grab the last number.\n    fn last(&self) -> i32 { self.1 }\n}\n\nfn difference<C: Contains>(container: &C) -> i32 {\n    container.last() - container.first()\n}\n\nfn main() {\n    let number_1 = 3;\n    let number_2 = 10;\n\n    let container = Container(number_1, number_2);\n\n    println!(\"Does container contain {} and {}: {}\",\n        &number_1, &number_2,\n        container.contains(&number_1, &number_2));\n    println!(\"First number: {}\", container.first());\n    println!(\"Last number: {}\", container.last());"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"struct Container(i32, i32);\n\n// A trait which checks if 2 items are stored inside of container.\n// Also retrieves first or last value.\ntrait Contains {\n    // Define generic types here which methods will be able to utilize.\n    type A;\n    type B;\n\n    fn contains(&self, _: &Self::A, _: &Self::B) -> bool;\n    fn first(&self) -> i32;\n    fn last(&self) -> i32;\n}\n\nimpl Contains for Container {\n    // Specify what types `A` and `B` are. If the `input` type\n    // is `Container(i32, i32)`, the `output` types are determined\n    // as `i32` and `i32`.\n    type A = i32;\n    type B = i32;\n\n    // `&Self::A` and `&Self::B` are also valid here.\n    fn contains(&self, number_1: &i32, number_2: &i32) -> bool {\n        (&self.0 == number_1) && (&self.1 == number_2)\n    }\n    // Grab the first number.\n    fn first(&self) -> i32 { self.0 }\n\n    // Grab the last number.\n    fn last(&self) -> i32 { self.1 }\n}\n\nfn difference<C: Contains>(container: &C) -> i32 {\n    container.last() - container.first()\n}\n\nfn main() {\n    let number_1 = 3;\n    let number_2 = 10;\n\n    let container = Container(number_1, number_2);\n\n    println!(\"Does container contain {} and {}: {}\",\n        &number_1, &number_2,\n        container.contains(&number_1, &number_2));\n    println!(\"First number: {}\", container.first());\n    println!(\"Last number: {}\", container.last());"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-phantom-type-parameters":{"intro":"In this lab, we explore the concept of phantom type parameters, which are type parameters that are checked statically at compile time and do not have any runtime behavior or values. We demonstrate their usage in Rust by combining std::marker::PhantomData with the concept of phantom type parameters to create tuples and structs that contain different data types.","steps":[{"title":"Phantom type parameters","body":["A phantom type parameter is one that doesn't show up at runtime, but is checked statically (and only) at compile time.","Data types can use extra generic type parameters to act as markers or to perform type checking at compile time. These extra parameters hold no storage values, and have no runtime behavior.","In the following example, we combine \\[std::marker::PhantomData\\] with the phantom type parameter concept to create tuples containing different data types."],"code":[{"lang":"rust","text":"use std::marker::PhantomData;\n\n// A phantom tuple struct which is generic over `A` with hidden parameter `B`.\n#[derive(PartialEq)] // Allow equality test for this type.\nstruct PhantomTuple<A, B>(A, PhantomData<B>);\n\n// A phantom type struct which is generic over `A` with hidden parameter `B`.\n#[derive(PartialEq)] // Allow equality test for this type.\nstruct PhantomStruct<A, B> { first: A, phantom: PhantomData<B> }\n\n// Note: Storage is allocated for generic type `A`, but not for `B`.\n//       Therefore, `B` cannot be used in computations.\n\nfn main() {\n    // Here, `f32` and `f64` are the hidden parameters.\n    // PhantomTuple type specified as `<char, f32>`.\n    let _tuple1: PhantomTuple<char, f32> = PhantomTuple('Q', PhantomData);\n    // PhantomTuple type specified as `<char, f64>`.\n    let _tuple2: PhantomTuple<char, f64> = PhantomTuple('Q', PhantomData);\n\n    // Type specified as `<char, f32>`.\n    let _struct1: PhantomStruct<char, f32> = PhantomStruct {\n        first: 'Q',\n        phantom: PhantomData,\n    };\n    // Type specified as `<char, f64>`.\n    let _struct2: PhantomStruct<char, f64> = PhantomStruct {\n        first: 'Q',\n        phantom: PhantomData,\n    };\n\n    // Compile-time Error! Type mismatch so these cannot be compared:\n    // println!(\"_tuple1 == _tuple2 yields: {}\",\n    //           _tuple1 == _tuple2);\n\n    // Compile-time Error! Type mismatch so these cannot be compared:\n    // println!(\"_struct1 == _struct2 yields: {}\",\n    //           _struct1 == _struct2);\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"use std::marker::PhantomData;\n\n// A phantom tuple struct which is generic over `A` with hidden parameter `B`.\n#[derive(PartialEq)] // Allow equality test for this type.\nstruct PhantomTuple<A, B>(A, PhantomData<B>);\n\n// A phantom type struct which is generic over `A` with hidden parameter `B`.\n#[derive(PartialEq)] // Allow equality test for this type.\nstruct PhantomStruct<A, B> { first: A, phantom: PhantomData<B> }\n\n// Note: Storage is allocated for generic type `A`, but not for `B`.\n//       Therefore, `B` cannot be used in computations.\n\nfn main() {\n    // Here, `f32` and `f64` are the hidden parameters.\n    // PhantomTuple type specified as `<char, f32>`.\n    let _tuple1: PhantomTuple<char, f32> = PhantomTuple('Q', PhantomData);\n    // PhantomTuple type specified as `<char, f64>`.\n    let _tuple2: PhantomTuple<char, f64> = PhantomTuple('Q', PhantomData);\n\n    // Type specified as `<char, f32>`.\n    let _struct1: PhantomStruct<char, f32> = PhantomStruct {\n        first: 'Q',\n        phantom: PhantomData,\n    };\n    // Type specified as `<char, f64>`.\n    let _struct2: PhantomStruct<char, f64> = PhantomStruct {\n        first: 'Q',\n        phantom: PhantomData,\n    };\n\n    // Compile-time Error! Type mismatch so these cannot be compared:\n    // println!(\"_tuple1 == _tuple2 yields: {}\",\n    //           _tuple1 == _tuple2);\n\n    // Compile-time Error! Type mismatch so these cannot be compared:\n    // println!(\"_struct1 == _struct2 yields: {}\",\n    //           _struct1 == _struct2);\n}"}],"source":"rust-lang/rust-by-example · MIT"},"labex-rust-testcase-unit-clarification":{"intro":"In this lab, the implementation of the Add trait with a phantom type parameter is examined using the example code provided in Rust.","steps":[{"title":"Testcase: unit clarification","body":["A useful method of unit conversions can be examined by implementing Add with a phantom type parameter. The Add trait is examined below:"],"code":[{"lang":"rust","text":"// This construction would impose: `Self + RHS = Output`\n// where RHS defaults to Self if not specified in the implementation.\npub trait Add<RHS = Self> {\n    type Output;\n\n    fn add(self, rhs: RHS) -> Self::Output;\n}\n\n// `Output` must be `T<U>` so that `T<U> + T<U> = T<U>`.\nimpl<U> Add for T<U> {\n    type Output = T<U>;\n    ...\n}"},{"lang":"rust","text":"use std::ops::Add;\nuse std::marker::PhantomData;\n\n/// Create void enumerations to define unit types.\n#[derive(Debug, Clone, Copy)]\nenum Inch {}\n#[derive(Debug, Clone, Copy)]\nenum Mm {}\n\n/// `Length` is a type with phantom type parameter `Unit`,\n/// and is not generic over the length type (that is `f64`).\n///\n/// `f64` already implements the `Clone` and `Copy` traits.\n#[derive(Debug, Clone, Copy)]\nstruct Length<Unit>(f64, PhantomData<Unit>);\n\n/// The `Add` trait defines the behavior of the `+` operator.\nimpl<Unit> Add for Length<Unit> {\n    type Output = Length<Unit>;\n\n    // add() returns a new `Length` struct containing the sum.\n    fn add(self, rhs: Length<Unit>) -> Length<Unit> {\n        // `+` calls the `Add` implementation for `f64`.\n        Length(self.0 + rhs.0, PhantomData)\n    }\n}\n\nfn main() {\n    // Specifies `one_foot` to have phantom type parameter `Inch`.\n    let one_foot:  Length<Inch> = Length(12.0, PhantomData);\n    // `one_meter` has phantom type parameter `Mm`.\n    let one_meter: Length<Mm>   = Length(1000.0, PhantomData);\n\n    // `+` calls the `add()` method we implemented for `Length<Unit>`.\n    //\n    // Since `Length` implements `Copy`, `add()` does not consume\n    // `one_foot` and `one_meter` but copies them into `self` and `rhs`.\n    let two_feet = one_foot + one_foot;\n    let two_meters = one_meter + one_meter;\n\n    // Addition works.\n    println!(\"one foot + one_foot = {:?} in\", two_feet.0);\n    println!(\"one meter + one_meter = {:?} mm\", two_meters.0);\n\n    // Nonsensical operations fail as they should:\n    // Compile-time Error: type mismatch.\n    //let one_feter = one_foot + one_meter;\n}"}]}],"commands":[],"reference":[{"path":"reference.rs","text":"use std::ops::Add;\nuse std::marker::PhantomData;\n\n/// Create void enumerations to define unit types.\n#[derive(Debug, Clone, Copy)]\nenum Inch {}\n#[derive(Debug, Clone, Copy)]\nenum Mm {}\n\n/// `Length` is a type with phantom type parameter `Unit`,\n/// and is not generic over the length type (that is `f64`).\n///\n/// `f64` already implements the `Clone` and `Copy` traits.\n#[derive(Debug, Clone, Copy)]\nstruct Length<Unit>(f64, PhantomData<Unit>);\n\n/// The `Add` trait defines the behavior of the `+` operator.\nimpl<Unit> Add for Length<Unit> {\n    type Output = Length<Unit>;\n\n    // add() returns a new `Length` struct containing the sum.\n    fn add(self, rhs: Length<Unit>) -> Length<Unit> {\n        // `+` calls the `Add` implementation for `f64`.\n        Length(self.0 + rhs.0, PhantomData)\n    }\n}\n\nfn main() {\n    // Specifies `one_foot` to have phantom type parameter `Inch`.\n    let one_foot:  Length<Inch> = Length(12.0, PhantomData);\n    // `one_meter` has phantom type parameter `Mm`.\n    let one_meter: Length<Mm>   = Length(1000.0, PhantomData);\n\n    // `+` calls the `add()` method we implemented for `Length<Unit>`.\n    //\n    // Since `Length` implements `Copy`, `add()` does not consume\n    // `one_foot` and `one_meter` but copies them into `self` and `rhs`.\n    let two_feet = one_foot + one_foot;\n    let two_meters = one_meter + one_meter;\n\n    // Addition works.\n    println!(\"one foot + one_foot = {:?} in\", two_feet.0);\n    println!(\"one meter + one_meter = {:?} mm\", two_meters.0);\n\n    // Nonsensical operations fail as they should:\n    // Compile-time Error: type mismatch.\n    //let one_feter = one_foot + one_meter;\n}"}],"source":"rust-lang/rust-by-example · MIT"}};
